cases.query:
query InvalidRelationSelection {
  customer(id: 999) {
    orderConnection(first: 1) {
      edges {
        node {
          missingField
        }
      }
    }
  }
}

query ImpossibleFragment {
  nodeCustomer(id: 7) {
    ... on Query {
      customer(id: 7) { id }
    }
  }
}

query OverlappingConflict {
  searchCustomer(id: 7) {
    ... on Node { detail: id }
    ... on Customer { detail: name }
  }
}

query Broken {
  customer(id: 7) ?
}

query HiddenSchema {
  __schema { queryType { name } }
}
